import{_ as a,o,c as d,a2 as t}from"./chunks/framework.DFu8lfqj.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"about/faq.md","filePath":"about/faq.md"}'),r={name:"about/faq.md"};function i(c,e,n,h,s,l){return o(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>汇总 README 与源码中最容易让人困惑的问题。涉及具体文件时都给出了对应章节链接。</p><h2 id="node-到底需要哪个版本" tabindex="-1">Node 到底需要哪个版本？ <a class="header-anchor" href="#node-到底需要哪个版本" aria-label="Permalink to &quot;Node 到底需要哪个版本？&quot;">​</a></h2><p>以 <code>package.json</code> 的 <code>engines</code> 为准：<strong><code>^20.19.0 || &gt;=22.12.0</code></strong>，即 Node 20.19+ 或 22.12+。README 安装章节里的「Node 16+ / 18+」是旧描述，Vite 7 已不支持这些版本。用 <code>node -v</code> 检查一下即可。详见<a href="/bird-admin-docs/guide/getting-started.html">快速开始</a>。</p><h2 id="需要会后端开发吗" tabindex="-1">需要会后端开发吗？ <a class="header-anchor" href="#需要会后端开发吗" aria-label="Permalink to &quot;需要会后端开发吗？&quot;">​</a></h2><p>不需要。README 明确说明这是纯前端仓库，代码与部署都可以前后端分离，前端开发者无需掌握后端代码。对接真实服务时配置 <code>VITE_API_URL</code> 与 <code>/api</code> 代理即可，见<a href="/bird-admin-docs/guide/configuration.html">环境与配置</a>。</p><h2 id="演示账户是什么-能改数据吗" tabindex="-1">演示账户是什么？能改数据吗？ <a class="header-anchor" href="#演示账户是什么-能改数据吗" aria-label="Permalink to &quot;演示账户是什么？能改数据吗？&quot;">​</a></h2><p>账户 <code>admin</code>，密码 <code>123456</code>。README 注明<strong>演示站数据无法修改</strong>，想体验完整功能请下载源码本地安装。另外，README 里的「演示站」链接实际指向 Gitee 仓库，并非独立线上 Demo，见<a href="/bird-admin-docs/resources/contact.html">联系与演示</a>。</p><h2 id="可以免费商用吗" tabindex="-1">可以免费商用吗？ <a class="header-anchor" href="#可以免费商用吗" aria-label="Permalink to &quot;可以免费商用吗？&quot;">​</a></h2><p>可以。项目遵循 <strong>Apache-2.0</strong> 协议，无需授权即可免费使用；第三方源码与二进制文件的版权信息另行标注。分发时记得保留许可证与版权声明，见<a href="/bird-admin-docs/about/license.html">版权与许可</a>。</p><h2 id="用-npm-还是-pnpm" tabindex="-1">用 npm 还是 pnpm？ <a class="header-anchor" href="#用-npm-还是-pnpm" aria-label="Permalink to &quot;用 npm 还是 pnpm？&quot;">​</a></h2><p>推荐 <strong>pnpm</strong>（README 徽章建议 ≥ 10.13.1）。项目带 <code>pnpm-lock.yaml</code> 与 <code>pnpm-workspace.yaml</code>，混用包管理器容易造成依赖版本漂移。</p><h2 id="端口-9094-可以改吗" tabindex="-1">端口 9094 可以改吗？ <a class="header-anchor" href="#端口-9094-可以改吗" aria-label="Permalink to &quot;端口 9094 可以改吗？&quot;">​</a></h2><p>可以，修改根目录 <code>.env</code> 的 <code>VITE_PORT</code> 后重启。端口被占用时 Vite 会自动尝试下一个可用端口（<code>strictPort: false</code>），注意看终端打印的实际地址。</p><h2 id="readme-里的项目预览图在哪" tabindex="-1">README 里的项目预览图在哪？ <a class="header-anchor" href="#readme-里的项目预览图在哪" aria-label="Permalink to &quot;README 里的项目预览图在哪？&quot;">​</a></h2><p>README 的「项目预览」章节目前只有标题、顶部也只有一段 <code>img</code> 占位文本；仓库 <code>src/assets/readme/</code> 下仅有 <code>logo.png</code>，没有界面截图。想看实际界面，请按<a href="/bird-admin-docs/guide/getting-started.html">快速开始</a>在本地运行项目。</p><h2 id="为什么-readme-说有-web-文件夹-仓库里找不到" tabindex="-1">为什么 README 说有 <code>web</code> 文件夹，仓库里找不到？ <a class="header-anchor" href="#为什么-readme-说有-web-文件夹-仓库里找不到" aria-label="Permalink to &quot;为什么 README 说有 `web` 文件夹，仓库里找不到？&quot;">​</a></h2><p>那是旧版目录结构的描述。当前版本的 <code>干净/完整</code> 前端代码直接位于根目录 <code>src/</code>，不存在 <code>web</code> 目录。以<a href="/bird-admin-docs/guide/project-structure.html">目录结构</a>为准。</p><h2 id="徽章写-vite-6-0-为什么依赖里是-7-x" tabindex="-1">徽章写 Vite &gt; 6.0，为什么依赖里是 7.x？ <a class="header-anchor" href="#徽章写-vite-6-0-为什么依赖里是-7-x" aria-label="Permalink to &quot;徽章写 Vite &gt; 6.0，为什么依赖里是 7.x？&quot;">​</a></h2><p>徽章表达的是<strong>最低版本门槛</strong>，实际锁定版本更高：Vite <code>^7.1.2</code>、Pinia <code>^3.0.3</code>、TypeScript <code>~5.8.3</code>、Element Plus <code>^2.10.7</code>。升级插件时注意 Vite 7 / Pinia 3 的大版本变化，完整对照见<a href="/bird-admin-docs/guide/tech-stack.html">技术栈与依赖</a>。</p><h2 id="接口请求-404-或跨域怎么办" tabindex="-1">接口请求 404 或跨域怎么办？ <a class="header-anchor" href="#接口请求-404-或跨域怎么办" aria-label="Permalink to &quot;接口请求 404 或跨域怎么办？&quot;">​</a></h2><p>两处一起检查：<code>.env.*</code> 中的 <code>VITE_API_URL</code>，以及 <code>build/vite/server.ts</code> 里 <code>/api</code> 代理的 <code>target</code>（当前为空字符串，需要填你的后端地址）。</p><h2 id="路由是-history-还是-hash-模式" tabindex="-1">路由是 history 还是 hash 模式？ <a class="header-anchor" href="#路由是-history-还是-hash-模式" aria-label="Permalink to &quot;路由是 history 还是 hash 模式？&quot;">​</a></h2><p>当前使用 <code>createWebHashHistory()</code>，地址带 <code>#/</code>。静态部署时通常不会出现 history 模式的刷新 404 问题；若页面空白，先确认访问地址包含 <code>#/</code> 且托管服务正确返回 <code>index.html</code>。</p><h2 id="无限子级权限已经做好了吗" tabindex="-1">无限子级权限已经做好了吗？ <a class="header-anchor" href="#无限子级权限已经做好了吗" aria-label="Permalink to &quot;无限子级权限已经做好了吗？&quot;">​</a></h2><p>README 把它列为目标特性。当前仓库可见的是<strong>静态路由自动收集</strong>（<code>import.meta.glob</code>）+ 登录白名单，完整的「权限树 → 动态注册路由 → 按钮级鉴权」链路尚未在源码中闭环，部分相关代码处于注释状态。详见<a href="/bird-admin-docs/guide/routing.html">路由与权限</a>。</p><h2 id="为什么-pnpm-run-dev-正常但-build-报错" tabindex="-1">为什么 <code>pnpm run dev</code> 正常但 <code>build</code> 报错？ <a class="header-anchor" href="#为什么-pnpm-run-dev-正常但-build-报错" aria-label="Permalink to &quot;为什么 `pnpm run dev` 正常但 `build` 报错？&quot;">​</a></h2><p><code>build</code> 会先执行 <code>vue-tsc -b</code> 做全量类型检查，开发模式不会。按报错修复类型问题即可，见<a href="/bird-admin-docs/guide/configuration.html">环境与配置</a>。</p><h2 id="还没解决问题" tabindex="-1">还没解决问题？ <a class="header-anchor" href="#还没解决问题" aria-label="Permalink to &quot;还没解决问题？&quot;">​</a></h2><ul><li><a href="/bird-admin-docs/resources/contact.html">联系与演示</a> —— 邮箱、QQ 群与提 Issue 的建议格式</li><li><a href="https://gitee.com/web_akai/bird-admin" target="_blank" rel="noreferrer">Gitee 仓库</a> —— 查看最新提交与 Issue 区</li><li><a href="/bird-admin-docs/guide/getting-started.html">快速开始</a> —— 按步骤重新核对一遍安装环境与命令</li></ul>',30)])])}const u=a(r,[["render",i]]);export{p as __pageData,u as default};
